const vp = window.__chatStore?.mainViewpoint;
if (vp) {
  ssp.cameraController.setViewpoint(vp);
} else {
  const roots = ssp.modelTool.getLoadedFloors().map((name) => ssp.modelTool.getFloorInfo(name)?.root).filter(Boolean);
  if (!roots.length) throw new Error('没有主视角或已加载模型');
  await ssp.cameraController.fitScene(roots, { view: 'iso' });
}
